pub(crate) const VG_AES_GCM_INIT_AESNI_PCLMUL_AVX_FEATURES: crate::cpu::Features = crate::cpu::Features::of(&["ssse3", "aes"]);

/// The AES-GCM key setup: writes the key context of the `key_len`-byte AES key at `key` to `*ctx`: its key schedule for `Nr = key_len / 4 + 6` rounds (FIPS 197 §5.2, as `vg_aes_expand_key` writes it) in the first `16 * (Nr + 1)` bytes, and the hash subkey `H = CIPH_K(0¹²⁸)` (NIST SP 800-38D §7.1 step 1) in bytes 240–255. The other bytes are unspecified. The other `vg_aes_gcm_*` functions read it, with `Nr` as their `rounds`.
///
/// Contract: `VG.Spec.Gcm.initContract`. The key context is `VG.Spec.Gcm.KeyRepr`. Constant time: only the pointers and `key_len` may affect timing, not the key.
///
/// This implementation encrypts with `vg_aes_ctr32_aesni` (and expands keys with `vg_aes_expand_key_scratch_aesni`) and hashes with `vg_ghash_pclmul`.
///
/// # Safety
///
/// * `key` must be valid for reads of `key_len` bytes.
/// * `ctx` must be valid for reads and writes of 256 bytes.
/// * `key_len` must be 16, 24 or 32.
/// * `ctx` must not overlap `key` (distinct Rust objects never do).
/// * Neither `key` nor `ctx` may overlap the return address on the stack or the 2576 bytes of stack below it, or wrap around the end of the address space (no Rust object does).
/// * The CPU must support the `ssse3` and `aes` target features.
#[unsafe(naked)]
pub(crate) unsafe extern "sysv64" fn vg_aes_gcm_init_aesni_pclmul_avx(key: *const u8, key_len: usize, ctx: *mut [u64; 32]) {
    core::arch::naked_asm!(
        "lea rsp, [rsp-2568]",
        "mov rcx, rsp",
        "add rcx, 8",
        "mov QWORD PTR [rcx+128], rbx",
        "mov QWORD PTR [rcx+136], rbp",
        "mov QWORD PTR [rcx+144], r12",
        "mov QWORD PTR [rcx+152], r13",
        "mov QWORD PTR [rcx+160], r14",
        "mov QWORD PTR [rcx+168], r15",
        "mov r15, rcx",
        "mov r13, rdx",
        "mov rbx, rsi",
        "shr rbx, 2",
        "add rbx, 6",
        "mov rcx, r15",
        "add rcx, 512",
        "call {vg_aes_expand_key_scratch_aesni}",
        "mov eax, 0",
        "mov QWORD PTR [r13+240], rax",
        "mov QWORD PTR [r13+248], rax",
        "mov QWORD PTR [r15+96], rax",
        "mov QWORD PTR [r15+104], rax",
        "mov rdi, r13",
        "mov rsi, rbx",
        "mov rdx, r15",
        "add rdx, 96",
        "mov rcx, r13",
        "add rcx, 240",
        "mov r8d, 1",
        "mov r9, r15",
        "add r9, 512",
        "call {vg_aes_ctr32_aesni}",
        "mov rbx, QWORD PTR [r15+128]",
        "mov rbp, QWORD PTR [r15+136]",
        "mov r12, QWORD PTR [r15+144]",
        "mov r13, QWORD PTR [r15+152]",
        "mov r14, QWORD PTR [r15+160]",
        "mov r15, QWORD PTR [r15+168]",
        "lea rsp, [rsp+2568]",
        "ret",
        ".p2align 6",
        vg_aes_expand_key_scratch_aesni = sym super::aes::vg_aes_expand_key_scratch_aesni,
        vg_aes_ctr32_aesni = sym super::aes::vg_aes_ctr32_aesni,
    )
}

