/// The CPU features `vg_aes_gcm_stream_init_pclmul` requires (`Artifact.features`).
pub(crate) const VG_AES_GCM_STREAM_INIT_PCLMUL_FEATURES: crate::cpu::Features = crate::cpu::Features::of(&["pclmulqdq", "ssse3"]);

